c = p.chapter("data", "Data and graph skills")
L = LS(c, "graphs-data", "Using graphs, climate data and photographs",
    ["Draw and read bar graphs and line graphs", "Calculate angles for a pie chart", "Read a climate graph", "Interpret a photograph or sketch in geography"],
    [("text", "Geographers use **graphs** to show data clearly. A **bar graph** compares quantities in separate groups (for example crop production by region). A **line graph** shows change over time (for example monthly temperature). A **pie chart** shows how a total is divided: the whole circle is 360°. Every graph needs a **title**, **labels** on the axes, a suitable **scale** and **units**."),
     ("key", "formule", "Pie chart angles", "Angle for a category = (value ÷ total) × 360°. Example: if cassava is 40 tonnes of a total of 200 tonnes, its angle is 40 ÷ 200 × 360 = **72°**. Check that all angles add up to 360° before drawing with a protractor."),
     ("key", "methode", "Climate graph", "A climate graph shows **temperature** as a line and **rainfall** as bars for each month. Read: (1) the highest and lowest monthly temperature and the **annual range** (highest − lowest); (2) the rainy months and the dry months; (3) the annual rainfall (add the monthly bars); then describe the climate. A hot place with rain all year is equatorial; hot with a long dry season is tropical."),
     ("text", "**Photographs and sketches.** To interpret a photograph, say what is in the **foreground** (near), **middle ground** and **background** (far), name features (relief, vegetation, buildings, rivers, farming), say what they show about the area (climate, human activities) and add a short sketch with labels. Always describe what you can see before explaining why."),
     ("key", "pieges", "Common mistakes", "- Do not start a vertical scale in the middle: begin at zero for bar graphs.\n- Pie chart angles must add up to 360°.\n- Describing a photograph is not the same as inventing facts: write only what the picture shows.")],
    [("Example 1: pie chart angle", "In a village, 30 of the 120 families grow coffee. What angle represents coffee on a pie chart?", ["Fraction = 30 ÷ 120 = 1/4.", "1/4 of 360° = 90°.", "Check: the other categories must give 270°."], "90°."),
     ("Example 2: annual range", "A town has a hottest month of 29 °C and a coolest month of 24 °C. What is the annual temperature range?", ["Range = highest − lowest.", "29 − 24 = 5.", "A small range is typical near the Equator."], "5 °C.")],
    F(bars([("Jan", 40, "blue"), ("Feb", 60, "blue"), ("Mar", 120, "blue"), ("Apr", 160, "blue"), ("May", 200, "blue")], unit="Rain (mm), invented figures", h=260), "Example of a rainfall bar graph", "Bar graph showing rainfall rising from January to May; invented figures."),
    [MCQ("A pie chart is a circle of how many degrees?", "360°", ["180°", "100°", "90°"], "All the categories together form 360°."),
     TF("A line graph is best for showing change over time.", True, "It follows values month by month or year by year."),
     NUM("In a survey of 80 pupils, 20 walk to school. What angle represents walkers in a pie chart? (degrees)", 90, "20 ÷ 80 × 360 = 90.", unit="°"),
     NUM("The total annual rainfall is the sum of the monthly values. Rain in four months is 150, 200, 250 and 100 mm; the other eight months have 0 mm. What is the total, in mm?", 700, "150 + 200 + 250 + 100 = 700.", unit="mm", tier="approfondissement"),
     OPEN("Explain how you would describe the climate of a place from a climate graph.", "State the temperature pattern (highest, lowest and range), then the rainfall pattern (wet months, dry months and annual total) and conclude which climate type it matches, with reasons.", "1 mark temperature; 1 mark rainfall; 1 mark conclusion.", points=3, tier="approfondissement"),
     PROB("Farmers in a division produce 100 tonnes of crops: cassava 50, maize 30 and groundnuts 20.",
          [("num", "Angle for cassava in a pie chart (degrees).", 180, "50 ÷ 100 × 360 = 180.", 0, "°", {}),
           ("num", "Angle for maize (degrees).", 108, "30 ÷ 100 × 360 = 108.", 0, "°", {}),
           ("num", "Angle for groundnuts (degrees).", 72, "20 ÷ 100 × 360 = 72.", 0, "°", {}),
           ("tf", "The three angles together equal 360°.", True, "180 + 108 + 72 = 360.", {})])],
    [("A bar graph needs", "labelled axes and a title", ["no title", "no units", "a pie slice"], "Clear labels make it readable."),
     ("The annual temperature range is the", "difference between the highest and lowest monthly means", ["sum of all months", "average rainfall", "rainy season length"], "Highest minus lowest."),
     ("Foreground in a photograph means", "the part nearest the viewer", ["the sky only", "the horizon", "the caption"], "Foreground is in front."),
     ("In a climate graph, rainfall is usually shown by", "bars", ["a pie", "a map", "a table only"], "Bars show the amount per month."),
     ("The angle for a category that is half the total is", "180°", ["90°", "360°", "50°"], "Half of 360° is 180°.")],
    ["Teacher to verify that the syllabus uses these graph types and conventions; all numbers in the graphs and exercises are invented."], tag="Form 4 graph skills")

p.write()
